    /// <summary>
    /// Asserts the extracted loot-table service against literal rows recorded from the accepted old-runtime baseline.
    /// Expected rows are independent constants and are never generated by this implementation. Run with
    /// -executeMethod Emberdelve.EditorTools.EmberdelveLootGoldenCaptureGate.Run.
    /// </summary>
