        [MenuItem("Emberdelve/Assert LootTable Golden Parity")]
        public static void Run()
        {
            _checks = 0;
            _failures = 0;
            List<UnityEngine.Object> cleanup = new List<UnityEngine.Object>();

            try
            {
                ItemCatalog catalog = AssetDatabase.LoadAssetAtPath<ItemCatalog>(EmberdelveAssetLibrary.ItemCatalogPath);
                LootTable ember = LoadTable("Loot_EmberChest.asset");
                LootTable sealedChest = LoadTable("Loot_SealedChest.asset");
                LootTable supply = LoadTable("Loot_SupplyChest.asset");
                LootTable hollow = LoadTable("Loot_Enemy_HollowServitor.asset");

                ItemInstanceAuthority productionAuthority = null;
                string catalogReason = null;
                string catalogPath = catalog != null ? AssetDatabase.GetAssetPath(catalog) : null;
                bool productionCatalogValid = catalog != null &&
                                              !catalog.IsTestCatalog &&
                                              string.Equals(catalogPath, EmberdelveAssetLibrary.ItemCatalogPath,
                                                  StringComparison.Ordinal) &&
                                              catalog.ItemCount > 0 &&
                                              catalog.AffixCount > 0 &&
                                              catalog.TryGetAuthority(out productionAuthority, out catalogReason) &&
                                              productionAuthority != null;
                Check(productionCatalogValid,
                    "saved production item catalog validates: path=" + (catalogPath ?? "<missing>") +
                    " testOnly=" + (catalog != null && catalog.IsTestCatalog) +
                    " items=" + (catalog != null ? catalog.ItemCount : 0) +
                    " affixes=" + (catalog != null ? catalog.AffixCount : 0) +
                    " reason=" + FormatReason(catalogReason));
                Check(ember != null && sealedChest != null && supply != null && hollow != null,
                    "four saved loot tables loaded");
                if (!productionCatalogValid || ember == null || sealedChest == null || supply == null || hollow == null)
                {
                    Debug.Log("[R8b1][GOLDEN][END] checks=" + _checks + " failures=" + _failures +
                              " capture skipped because a saved fixture did not load");
                }
                else
                {
                    ItemIdentityIssuer issuer = ItemIdentityIssuer.CreateSeeded(new DeterministicRng(UidSeed));
                    Debug.Log("[R8b1][GOLDEN][BEGIN] uidSeed=0x" + UidSeed.ToString("X16", CultureInfo.InvariantCulture) +
                              " issuer=shared-across-fixed-cases");

                    CaptureCase[] cases =
                    {
                        new CaptureCase { Name = "ember-a", Table = ember, Seed = 0x0123456789ABCDEFUL },
                        new CaptureCase { Name = "ember-b", Table = ember, Seed = 0x0BADF00D12345678UL },
                        new CaptureCase { Name = "sealed-a", Table = sealedChest, Seed = 0xCAFEBABE87654321UL },
                        new CaptureCase { Name = "sealed-b", Table = sealedChest, Seed = 0x1020304050607080UL },
                        new CaptureCase { Name = "supply-a", Table = supply, Seed = 0x3141592653589793UL },
                        new CaptureCase { Name = "hollow-a", Table = hollow, Seed = 0x2718281828459045UL }
                    };

                    for (int i = 0; i < cases.Length; i++)
                    {
                        CapturePositive(cases[i], catalog, issuer);
                    }

                    LootTable gearTable = FindGearTable(ember, sealedChest, supply, hollow);
                    Check(gearTable != null, "saved fixture includes a gear-instance table");
                    if (gearTable != null)
                    {
                        CaptureNegative("null-catalog-gear-table", gearTable, null,
                            ItemIdentityIssuer.CreateSeeded(new DeterministicRng(0xA11CE55EEDUL)),
                            0xA11CE55EEDUL);

                        LootTable invalidRarity = CloneTable(gearTable);
                        cleanup.Add(invalidRarity);
                        if (TrySetInvalidRarityOnFirstGearEntry(invalidRarity))
                        {
                            CaptureNegative("invalid-rarity-profile", invalidRarity, catalog,
                                ItemIdentityIssuer.CreateSeeded(new DeterministicRng(0x1BADB002UL)),
                                0x1BADB002UL);
                        }
                        else
                        {
                            Check(false, "saved gear table clone has entries for invalid-rarity negative");
                        }
                    }

                    LootTable emptyTable = CloneTable(supply);
                    cleanup.Add(emptyTable);
                    emptyTable.entries = Array.Empty<LootEntry>();
                    CaptureNegative("empty-entry-table", emptyTable, catalog,
                        ItemIdentityIssuer.CreateSeeded(new DeterministicRng(0xE0017UL)), 0xE0017UL);

                    CaptureNullOutput("null-output", ember, catalog,
                        ItemIdentityIssuer.CreateSeeded(new DeterministicRng(0x0BADCAFEUL)), 0x0BADCAFEUL);

                    Debug.Log("[R8b1][GOLDEN][END] checks=" + _checks + " failures=" + _failures +
                              " finalMinted=" + issuer.MintedCount);
                }
            }
            catch (Exception e)
            {
                _failures++;
                Debug.LogException(e);
            }
            finally
            {
                for (int i = 0; i < cleanup.Count; i++)
                {
                    if (cleanup[i] != null) UnityEngine.Object.DestroyImmediate(cleanup[i]);
                }
            }

            Debug.Log("[Emberdelve][LootGoldenCapture] " + (_failures == 0 ? "PASS" : "FAIL") +
                      " checks=" + _checks + " failures=" + _failures);
            EditorApplication.Exit(_failures == 0 ? 0 : 1);
        }

        private static LootTable LoadTable(string fileName)
        {
            return AssetDatabase.LoadAssetAtPath<LootTable>(DataFolder + fileName);
        }

        private static LootTable FindGearTable(params LootTable[] tables)
        {
            for (int i = 0; i < tables.Length; i++)
            {
                if (tables[i] != null && tables[i].RequestsGearInstances) return tables[i];
            }

            return null;
        }

        private static LootTable CloneTable(LootTable source)
        {
            LootTable clone = UnityEngine.Object.Instantiate(source);
            clone.name = source.name + "_R8b1CaptureClone";
            clone.hideFlags = HideFlags.HideAndDontSave;

            if (source.entries != null)
            {
                clone.entries = new LootEntry[source.entries.Length];
                for (int i = 0; i < source.entries.Length; i++)
                {
                    LootEntry entry = source.entries[i];
                    if (entry == null) continue;

                    clone.entries[i] = new LootEntry
                    {
                        item = entry.item,
                        minAmount = entry.minAmount,
                        maxAmount = entry.maxAmount,
                        weight = entry.weight,
                        maxCopies = entry.maxCopies,
                        affixRarity = entry.affixRarity
                    };
                }
            }

            return clone;
        }

        private static bool TrySetInvalidRarityOnFirstGearEntry(LootTable table)
        {
            if (table == null || table.entries == null) return false;

            for (int i = 0; i < table.entries.Length; i++)
            {
                LootEntry entry = table.entries[i];
                if (entry == null || !entry.RequestsGearInstance) continue;
                entry.affixRarity = (AffixRarity)99;
                return true;
            }

            return false;
        }

        private static void CapturePositive(CaptureCase capture, ItemCatalog catalog, ItemIdentityIssuer issuer)
        {
            List<LootDrop> drops = new List<LootDrop>();
            int mintedBefore = issuer.MintedCount;
            bool ok = capture.Table.TryRollSeeded(capture.Seed, drops, catalog, issuer, out string reason);
            Check(ok, capture.Name + " saved table roll succeeds");

            string tableLine = "[R8b1][GOLDEN][TABLE] case=" + capture.Name +
                               " tableId=" + capture.Table.tableId +
                               " seed=0x" + capture.Seed.ToString("X16", CultureInfo.InvariantCulture) +
                               " success=" + ok +
                               " reason=" + FormatReason(reason) +
                               " mintedBefore=" + mintedBefore +
                               " mintedAfter=" + issuer.MintedCount +
                               " dropCount=" + drops.Count;
            Debug.Log(tableLine);
            Check(ExpectedTableLines.TryGetValue(capture.Name, out string expectedTable) && tableLine == expectedTable,
                capture.Name + " matches accepted old-runtime table literal");

            string[] expectedDrops = ExpectedDrops(capture.Name);
            Check(drops.Count == expectedDrops.Length, capture.Name + " matches accepted old-runtime drop count");
            for (int i = 0; i < drops.Count; i++)
            {
                string dropLine = "[R8b1][GOLDEN][DROP] case=" + capture.Name + " " + FormatDrop(i, drops[i]);
                Debug.Log(dropLine);
                Check(i < expectedDrops.Length && dropLine == expectedDrops[i],
                    capture.Name + " drop " + i + " matches accepted old-runtime literal");
            }
        }

        private static void CaptureNegative(string name, LootTable table, ItemCatalog catalog,
            ItemIdentityIssuer issuer, ulong seed)
        {
            List<LootDrop> drops = new List<LootDrop>();
            int mintedBefore = issuer.MintedCount;
            bool ok = table.TryRollSeeded(seed, drops, catalog, issuer, out string reason);
            bool preserved = !ok && drops.Count == 0 && issuer.MintedCount == mintedBefore;
            Check(preserved, name + " refuses atomically without minting");

            string line = "[R8b1][GOLDEN][NEGATIVE] name=" + name +
                          " tableId=" + table.tableId +
                          " seed=0x" + seed.ToString("X16", CultureInfo.InvariantCulture) +
                          " returned=" + ok +
                          " outputCount=" + drops.Count +
                          " mintedBefore=" + mintedBefore +
                          " mintedAfter=" + issuer.MintedCount +
                          " reason=" + FormatReason(reason);
            Debug.Log(line);
            Check(ExpectedNegativeLines.TryGetValue(name, out string expected) && line == expected,
                name + " matches accepted old-runtime refusal literal");
        }

        private static void CaptureNullOutput(string name, LootTable table, ItemCatalog catalog,
            ItemIdentityIssuer issuer, ulong seed)
        {
            int mintedBefore = issuer.MintedCount;
            bool ok = table.TryRollSeeded(seed, null, catalog, issuer, out string reason);
            bool preserved = !ok && issuer.MintedCount == mintedBefore;
            Check(preserved, name + " refuses without minting");

            string line = "[R8b1][GOLDEN][NEGATIVE] name=" + name +
                          " tableId=" + table.tableId +
                          " seed=0x" + seed.ToString("X16", CultureInfo.InvariantCulture) +
                          " returned=" + ok +
                          " outputCount=<null>" +
                          " mintedBefore=" + mintedBefore +
                          " mintedAfter=" + issuer.MintedCount +
                          " reason=" + FormatReason(reason);
            Debug.Log(line);
            Check(ExpectedNegativeLines.TryGetValue(name, out string expected) && line == expected,
                name + " matches accepted old-runtime refusal literal");
        }

        private static string[] ExpectedDrops(string caseName)
        {
            switch (caseName)
            {
                case "ember-a": return ExpectedDrops_ember_a;
                case "ember-b": return ExpectedDrops_ember_b;
                case "sealed-a": return ExpectedDrops_sealed_a;
                case "sealed-b": return ExpectedDrops_sealed_b;
                case "supply-a": return ExpectedDrops_supply_a;
                case "hollow-a": return ExpectedDrops_hollow_a;
                default: return Array.Empty<string>();
            }
        }

        private static string FormatDrop(int index, LootDrop drop)
        {
            StringBuilder text = new StringBuilder();
            text.Append("index=").Append(index)
                .Append(" itemId=").Append(drop.Item != null ? drop.Item.itemId : "<null>")
                .Append(" amount=").Append(drop.Amount.ToString(CultureInfo.InvariantCulture))
                .Append(" rarity=").Append(drop.Rarity)
                .Append(" uid=").Append(string.IsNullOrEmpty(drop.UidText) ? "<none>" : drop.UidText)
                .Append(" affixes=[");

            if (drop.Instance != null)
            {
                for (int i = 0; i < drop.Instance.Affixes.Count; i++)
                {
                    if (i > 0) text.Append(';');
                    AffixRecord affix = drop.Instance.Affixes[i];
                    text.Append(affix.Id).Append(',')
                        .Append(affix.CanonicalKey).Append(',')
                        .Append(affix.Value.ToString("R", CultureInfo.InvariantCulture));
                }
            }

            return text.Append(']').ToString();
        }

        private static string FormatReason(string reason)
        {
            if (string.IsNullOrEmpty(reason)) return "<none>";
            return '"' + reason.Replace("\\", "\\\\").Replace("\"", "\\\"")
                               .Replace("\r", "\\r").Replace("\n", "\\n") + '"';
        }

        private static void Check(bool ok, string label)
        {
            _checks++;
            if (ok) return;
            _failures++;
            Debug.LogError("[R8b1][GOLDEN][FAIL] " + label);
        }
    }
